// src/components/PatientApproval.tsx

import React, { useState, useEffect } from 'react';
import { 
  UserCheck, 
  UserX, 
  Link, 
  Search, 
  Clock, 
  CheckCircle2, 
  AlertCircle,
  Sparkles,
  User,
  Mail,
  Phone,
  Calendar,
  Loader2,
  RefreshCw,
  ShieldCheck,
  Users,
  Link2,
  ArrowRight
} from 'lucide-react';
import { api } from '../utils/api';

interface PendingPatient {
  id: string;
  userId: string;
  name: string;
  email: string;
  phone: string;
  status: string;
  treatmentType: string;
  createdAt: string;
  user: {
    id: string;
    name: string;
    email: string;
    phone: string;
    status: string;
  };
}

interface ExistingPatient {
  id: string;
  name: string;
  email: string;
  phone: string;
  status: string;
  treatmentType: string;
}

interface PatientApprovalProps {
  onApprove?: () => void;
  onSync?: () => void;
  isSyncing?: boolean;
}

export function PatientApproval({ 
  onApprove, 
  onSync, 
  isSyncing 
}: PatientApprovalProps) {
  const [pendingPatients, setPendingPatients] = useState<PendingPatient[]>([]);
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedPatient, setSelectedPatient] = useState<PendingPatient | null>(null);
  const [showLinkModal, setShowLinkModal] = useState(false);
  const [existingPatients, setExistingPatients] = useState<ExistingPatient[]>([]);
  const [linkSearchTerm, setLinkSearchTerm] = useState('');
  const [selectedExistingPatient, setSelectedExistingPatient] = useState<ExistingPatient | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  // Buscar pacientes pendentes
  const loadPendingPatients = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('auth_token');
      if (!token) {
        console.error('Token não encontrado');
        return;
      }

      const response = await fetch('http://localhost:5000/api/patients/pending', {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });

      const data = await response.json();
      console.log('📡 Pending patients:', data);

      if (data.success) {
        setPendingPatients(data.patients || []);
      } else {
        setErrorMessage(data.error || 'Erro ao carregar pacientes pendentes');
      }
    } catch (error) {
      console.error('❌ Error loading pending patients:', error);
      setErrorMessage('Erro ao conectar ao servidor');
    } finally {
      setLoading(false);
    }
  };

  // Buscar pacientes existentes para vincular
  const loadExistingPatients = async () => {
    try {
      const token = localStorage.getItem('auth_token');
      if (!token) return;

      const response = await fetch('http://localhost:5000/api/patients', {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });

      const data = await response.json();
      console.log('📡 Existing patients:', data);

      if (data.success) {
        setExistingPatients(data.patients || []);
      }
    } catch (error) {
      console.error('❌ Error loading existing patients:', error);
    }
  };

  // Aprovar paciente
  const handleApprove = async (patientId: string) => {
    setProcessing(patientId);
    try {
      const token = localStorage.getItem('auth_token');
      if (!token) {
        setErrorMessage('Token não encontrado');
        return;
      }

      const response = await fetch(`http://localhost:5000/api/patients/approve/${patientId}`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      const data = await response.json();
      console.log('📡 Approve response:', data);

      if (data.success) {
        setSuccessMessage(`✅ ${data.patient.name} aprovado com sucesso!`);
        setPendingPatients(prev => prev.filter(p => p.id !== patientId));
        if (onApprove) onApprove();
        setTimeout(() => setSuccessMessage(null), 3000);
      } else {
        setErrorMessage(data.error || 'Erro ao aprovar paciente');
        setTimeout(() => setErrorMessage(null), 3000);
      }
    } catch (error) {
      console.error('❌ Error approving patient:', error);
      setErrorMessage('Erro ao aprovar paciente');
      setTimeout(() => setErrorMessage(null), 3000);
    } finally {
      setProcessing(null);
    }
  };

  // Rejeitar paciente
  const handleReject = async (patientId: string) => {
    if (!window.confirm('Tem certeza que deseja rejeitar este paciente?')) return;

    setProcessing(patientId);
    try {
      const token = localStorage.getItem('auth_token');
      if (!token) {
        setErrorMessage('Token não encontrado');
        return;
      }

      const response = await fetch(`http://localhost:5000/api/patients/reject/${patientId}`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      const data = await response.json();
      console.log('📡 Reject response:', data);

      if (data.success) {
        setSuccessMessage(`❌ ${data.patient.name} rejeitado.`);
        setPendingPatients(prev => prev.filter(p => p.id !== patientId));
        if (onApprove) onApprove();
        setTimeout(() => setSuccessMessage(null), 3000);
      } else {
        setErrorMessage(data.error || 'Erro ao rejeitar paciente');
        setTimeout(() => setErrorMessage(null), 3000);
      }
    } catch (error) {
      console.error('❌ Error rejecting patient:', error);
      setErrorMessage('Erro ao rejeitar paciente');
      setTimeout(() => setErrorMessage(null), 3000);
    } finally {
      setProcessing(null);
    }
  };

  // Abrir modal de vinculação
  const handleOpenLinkModal = (patient: PendingPatient) => {
    setSelectedPatient(patient);
    setShowLinkModal(true);
    loadExistingPatients();
    setLinkSearchTerm('');
    setSelectedExistingPatient(null);
  };

  // Vincular paciente
  const handleLink = async () => {
    if (!selectedPatient || !selectedExistingPatient) {
      setErrorMessage('Selecione um paciente para vincular');
      return;
    }

    setProcessing('linking');
    try {
      const token = localStorage.getItem('auth_token');
      if (!token) {
        setErrorMessage('Token não encontrado');
        return;
      }

      const response = await fetch('http://localhost:5000/api/patients/link', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          email: selectedExistingPatient.email,
          patientId: selectedPatient.id,
          userId: selectedPatient.userId
        })
      });

      const data = await response.json();
      console.log('📡 Link response:', data);

      if (data.success) {
        setSuccessMessage(`🔗 ${data.linkedPatient.name} vinculado com sucesso!`);
        setPendingPatients(prev => prev.filter(p => p.id !== selectedPatient.id));
        setShowLinkModal(false);
        setSelectedPatient(null);
        setSelectedExistingPatient(null);
        if (onApprove) onApprove();
        setTimeout(() => setSuccessMessage(null), 3000);
      } else {
        setErrorMessage(data.error || 'Erro ao vincular paciente');
        setTimeout(() => setErrorMessage(null), 3000);
      }
    } catch (error) {
      console.error('❌ Error linking patient:', error);
      setErrorMessage('Erro ao vincular paciente');
      setTimeout(() => setErrorMessage(null), 3000);
    } finally {
      setProcessing(null);
    }
  };

  // Carregar ao montar
  useEffect(() => {
    loadPendingPatients();
  }, []);

  // Filtrar pacientes pendentes
  const filteredPatients = pendingPatients.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.phone.includes(searchTerm)
  );

  // Filtrar pacientes existentes
  const filteredExisting = existingPatients.filter(p =>
    p.id !== selectedPatient?.id &&
    (p.name.toLowerCase().includes(linkSearchTerm.toLowerCase()) ||
     p.email.toLowerCase().includes(linkSearchTerm.toLowerCase()) ||
     p.phone.includes(linkSearchTerm))
  );

  return (
    <div className="max-w-6xl mx-auto space-y-6" id="patient-approval">
      {/* Header */}
      <div className="bg-white rounded-2xl p-6 sm:p-8 border border-slate-200 shadow-xs">
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-2">
              <span className="text-xs font-semibold text-teal-800 bg-teal-50 border border-teal-200 px-2.5 py-0.5 rounded-full">
                Aprovação de Pacientes
              </span>
              <span className="px-2.5 py-0.5 text-xs font-bold rounded-full bg-amber-100 text-amber-800 border border-amber-200">
                {pendingPatients.length} pendentes
              </span>
            </div>
            <h1 className="font-serif-luxury text-2xl sm:text-3xl font-bold text-slate-900 mt-1">
              Novos Cadastros Aguardando Aprovação
            </h1>
            <p className="text-xs text-slate-500 mt-0.5">
              Pacientes que se cadastraram e aguardam sua aprovação para acessar o sistema.
            </p>
          </div>

          <button
            onClick={loadPendingPatients}
            disabled={loading}
            className="flex items-center gap-1.5 px-4 py-2.5 bg-slate-900 hover:bg-slate-800 text-white text-xs font-semibold rounded-xl shadow-xs transition cursor-pointer disabled:opacity-50"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
            <span>{loading ? 'Carregando...' : 'Atualizar Lista'}</span>
          </button>
        </div>

        {/* Messages */}
        {successMessage && (
          <div className="mt-4 p-3 bg-emerald-50 border border-emerald-200 text-emerald-800 rounded-xl text-xs flex items-center gap-2">
            <CheckCircle2 className="w-4 h-4 text-emerald-600 shrink-0" />
            <span>{successMessage}</span>
          </div>
        )}

        {errorMessage && (
          <div className="mt-4 p-3 bg-rose-50 border border-rose-200 text-rose-800 rounded-xl text-xs flex items-center gap-2">
            <AlertCircle className="w-4 h-4 text-rose-600 shrink-0" />
            <span>{errorMessage}</span>
          </div>
        )}
      </div>

      {/* Search Bar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-xs">
        <div className="relative">
          <Search className="w-4 h-4 text-slate-400 absolute left-3.5 top-3.5" />
          <input
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar por nome, e-mail ou telefone..."
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/20 focus:border-teal-500 focus:bg-white text-slate-900"
          />
        </div>
      </div>

      {/* Loading State */}
      {loading ? (
        <div className="p-12 text-center bg-white rounded-2xl border border-slate-200">
          <Loader2 className="w-8 h-8 text-teal-600 animate-spin mx-auto mb-3" />
          <p className="text-sm font-medium text-slate-700">Carregando pacientes pendentes...</p>
        </div>
      ) : pendingPatients.length === 0 ? (
        <div className="p-12 text-center bg-white rounded-2xl border border-slate-200">
          <CheckCircle2 className="w-12 h-12 text-teal-500 mx-auto mb-3" />
          <h3 className="font-bold text-slate-900 text-base">Nenhum paciente aguardando aprovação</h3>
          <p className="text-xs text-slate-500 mt-1 max-w-md mx-auto">
            Todos os cadastros foram aprovados ou não há novos pacientes pendentes.
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          {filteredPatients.map((patient) => (
            <div
              key={patient.id}
              className="bg-white rounded-xl border border-slate-200 p-5 shadow-xs hover:border-teal-300 transition"
            >
              <div className="flex flex-wrap items-start justify-between gap-4">
                {/* Patient Info */}
                <div className="flex items-start gap-4 flex-1 min-w-0">
                  <div className="w-12 h-12 rounded-xl bg-teal-50 border border-teal-200 flex items-center justify-center text-teal-700 font-bold text-base shrink-0">
                    {patient.name.charAt(0)}
                  </div>
                  <div className="space-y-1 min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <h3 className="font-bold text-slate-900 text-base truncate">
                        {patient.name}
                      </h3>
                      <span className="px-2 py-0.5 text-[10px] font-bold rounded-full bg-amber-50 text-amber-800 border border-amber-200">
                        Aguardando Aprovação
                      </span>
                    </div>
                    <div className="flex flex-wrap gap-3 text-xs text-slate-600">
                      <span className="flex items-center gap-1">
                        <Mail className="w-3.5 h-3.5 text-slate-400" />
                        {patient.email}
                      </span>
                      <span className="flex items-center gap-1">
                        <Phone className="w-3.5 h-3.5 text-slate-400" />
                        {patient.phone}
                      </span>
                      <span className="flex items-center gap-1">
                        <Calendar className="w-3.5 h-3.5 text-slate-400" />
                        Cadastro: {new Date(patient.createdAt).toLocaleDateString('pt-BR')}
                      </span>
                    </div>
                    {patient.treatmentType && (
                      <p className="text-xs font-medium text-teal-700">
                        Tratamento: {patient.treatmentType}
                      </p>
                    )}
                  </div>
                </div>

                {/* Actions */}
                <div className="flex items-center gap-2 flex-wrap">
                  {/* Verificar se já existe paciente com mesmo email */}
                  {existingPatients.some(p => p.email === patient.email) && (
                    <button
                      onClick={() => handleOpenLinkModal(patient)}
                      disabled={processing === patient.id}
                      className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold bg-amber-600 hover:bg-amber-700 text-white rounded-lg transition cursor-pointer disabled:opacity-50"
                      title="Vincular com paciente existente"
                    >
                      <Link2 className="w-3.5 h-3.5" />
                      <span>Vincular</span>
                    </button>
                  )}

                  <button
                    onClick={() => handleApprove(patient.id)}
                    disabled={processing === patient.id}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg transition cursor-pointer disabled:opacity-50"
                  >
                    {processing === patient.id ? (
                      <Loader2 className="w-3.5 h-3.5 animate-spin" />
                    ) : (
                      <UserCheck className="w-3.5 h-3.5" />
                    )}
                    <span>Aprovar</span>
                  </button>

                  <button
                    onClick={() => handleReject(patient.id)}
                    disabled={processing === patient.id}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold bg-rose-600 hover:bg-rose-700 text-white rounded-lg transition cursor-pointer disabled:opacity-50"
                  >
                    <UserX className="w-3.5 h-3.5" />
                    <span>Rejeitar</span>
                  </button>
                </div>
              </div>

              {/* Mensagem de duplicata */}
              {existingPatients.some(p => p.email === patient.email) && (
                <div className="mt-3 p-2.5 bg-amber-50 border border-amber-200 rounded-lg text-xs text-amber-800 flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 text-amber-600 shrink-0" />
                  <span>
                    ⚠️ Já existe um paciente cadastrado com o e-mail <strong>{patient.email}</strong>. 
                    Clique em <strong>"Vincular"</strong> para conectar este cadastro ao paciente existente.
                  </span>
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Modal: Vincular Paciente */}
      {showLinkModal && selectedPatient && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs overflow-y-auto">
          <div className="relative w-full max-w-2xl bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden my-6">
            {/* Header */}
            <div className="p-6 bg-slate-900 text-white border-b border-slate-800">
              <div className="flex items-center justify-between">
                <div>
                  <span className="text-xs font-semibold uppercase tracking-wider text-teal-300">
                    Vincular Paciente
                  </span>
                  <h2 className="text-xl font-bold tracking-tight text-white mt-0.5">
                    Vincular Cadastro a Paciente Existente
                  </h2>
                </div>
                <button
                  onClick={() => setShowLinkModal(false)}
                  className="p-2 text-slate-400 hover:text-white rounded-lg hover:bg-slate-800 transition cursor-pointer"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
            </div>

            {/* Content */}
            <div className="p-6 space-y-4">
              <div className="p-4 bg-teal-50 border border-teal-200 rounded-xl">
                <p className="text-xs text-teal-900">
                  <strong>Cadastro pendente:</strong> {selectedPatient.name} ({selectedPatient.email})
                </p>
                <p className="text-xs text-teal-700 mt-1">
                  Selecione abaixo o paciente existente para vincular este cadastro.
                </p>
              </div>

              {/* Search */}
              <div className="relative">
                <Search className="w-4 h-4 text-slate-400 absolute left-3 top-3" />
                <input
                  type="text"
                  value={linkSearchTerm}
                  onChange={(e) => setLinkSearchTerm(e.target.value)}
                  placeholder="Buscar paciente existente por nome, e-mail ou telefone..."
                  className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/20 focus:border-teal-500 focus:bg-white"
                />
              </div>

              {/* Lista de pacientes existentes */}
              <div className="max-h-60 overflow-y-auto space-y-2">
                {filteredExisting.length === 0 ? (
                  <div className="p-4 text-center text-slate-500 text-xs">
                    {linkSearchTerm ? 'Nenhum paciente encontrado com esse termo' : 'Carregando pacientes existentes...'}
                  </div>
                ) : (
                  filteredExisting.map((p) => (
                    <button
                      key={p.id}
                      onClick={() => setSelectedExistingPatient(p)}
                      className={`w-full p-3 text-left rounded-xl border transition cursor-pointer flex items-center justify-between ${
                        selectedExistingPatient?.id === p.id
                          ? 'border-teal-600 bg-teal-50/70 shadow-xs'
                          : 'border-slate-200 hover:border-slate-300 hover:bg-slate-50'
                      }`}
                    >
                      <div>
                        <p className="font-bold text-slate-900 text-sm">{p.name}</p>
                        <p className="text-xs text-slate-500">{p.email} • {p.phone}</p>
                        <p className="text-[10px] font-medium text-teal-700">{p.treatmentType}</p>
                      </div>
                      {selectedExistingPatient?.id === p.id && (
                        <CheckCircle2 className="w-5 h-5 text-teal-600" />
                      )}
                    </button>
                  ))
                )}
              </div>

              {/* Actions */}
              <div className="pt-4 border-t border-slate-200 flex items-center justify-end gap-3">
                <button
                  onClick={() => setShowLinkModal(false)}
                  className="px-4 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-100 rounded-xl transition cursor-pointer"
                >
                  Cancelar
                </button>
                <button
                  onClick={handleLink}
                  disabled={!selectedExistingPatient || processing === 'linking'}
                  className="flex items-center gap-2 px-5 py-2.5 text-xs font-semibold bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white rounded-xl shadow-xs transition cursor-pointer"
                >
                  {processing === 'linking' ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : (
                    <Link2 className="w-4 h-4" />
                  )}
                  <span>Vincular Paciente</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}